pub(super) fn missing_constraint_edge(
    facets: &[RecoveredFacet],
    tet_edges: &HashSet<[usize; 2]>,
) -> Option<[usize; 2]> {
    recovered_constraint_edges_sorted(facets)
        .into_iter()
        .find(|edge| !tet_edges.contains(edge))
}

pub(super) fn carve_exterior_tets(
    points: &[Point],
    tets: Vec<[usize; 4]>,
    facets: &[RecoveredFacet],
) -> Vec<[usize; 4]> {
    if tets.is_empty() {
        return tets;
    }

    let protected_faces = recovered_facet_set(facets);
    let face_map = tet_face_incidence(&tets);
    let mut outside = vec![false; tets.len()];
    let mut queue = VecDeque::new();

    let mut boundary_seeds: Vec<_> = face_map
        .iter()
        .filter_map(|(face, owners)| {
            (owners.len() == 1 && !protected_faces.contains(face)).then_some((*face, owners[0]))
        })
        .collect();
    boundary_seeds.sort_unstable_by_key(|(face, _)| *face);
    for (_, owner) in boundary_seeds {
        if !outside[owner] {
            outside[owner] = true;
            queue.push_back(owner);
        }
    }

    while let Some(tet_idx) = queue.pop_front() {
        for face in tet_faces(tets[tet_idx]) {
            if protected_faces.contains(&face) {
                continue;
            }
            let Some(owners) = face_map.get(&face) else {
                continue;
            };
            for &neighbor in owners {
                if !outside[neighbor] {
                    outside[neighbor] = true;
                    queue.push_back(neighbor);
                }
            }
        }
    }

    let classifier = SurfaceClassifier::new(facets);
    for seed in 0..tets.len() {
        if outside[seed] {
            continue;
        }
        let component = flood_tet_component(seed, &tets, &face_map, &protected_faces, &outside);
        let probe = tet_centroid(points, tets[seed]);
        if !classifier.contains(points, probe) {
            for idx in component {
                outside[idx] = true;
            }
        }
    }

    if outside.iter().all(|is_outside| *is_outside) {
        return tets;
    }

    tets.into_iter()
        .enumerate()
        .filter_map(|(idx, tet)| (!outside[idx]).then_some(tet))
        .collect()
}

pub(super) fn compact_tet_mesh(
    points: Vec<Point>,
    tets: Vec<[usize; 4]>,
    facets: Vec<RecoveredFacet>,
) -> (Vec<Point>, Vec<[usize; 4]>, Vec<RecoveredFacet>) {
    let mut used = vec![false; points.len()];
    for tet in &tets {
        for &node in tet {
            used[node] = true;
        }
    }

    let mut remap = vec![None; points.len()];
    let mut compact_points = Vec::new();
    for (idx, point) in points.into_iter().enumerate() {
        if used[idx] {
            remap[idx] = Some(compact_points.len());
            compact_points.push(point);
        }
    }

    let compact_tets: Vec<[usize; 4]> = tets
        .into_iter()
        .map(|tet| {
            [
                remap[tet[0]].expect("tet node must have been remapped"),
                remap[tet[1]].expect("tet node must have been remapped"),
                remap[tet[2]].expect("tet node must have been remapped"),
                remap[tet[3]].expect("tet node must have been remapped"),
            ]
        })
        .collect();
    let retained_faces = tet_face_set(&compact_tets);

    let mut seen = HashSet::new();
    let mut compact_facets = Vec::new();
    for facet in facets {
        let Some(a) = remap[facet.nodes[0]] else {
            continue;
        };
        let Some(b) = remap[facet.nodes[1]] else {
            continue;
        };
        let Some(c) = remap[facet.nodes[2]] else {
            continue;
        };
        let remapped = RecoveredFacet {
            nodes: [a, b, c],
            marker: facet.marker,
        };
        let face = sorted3(remapped.nodes);
        if retained_faces.contains(&face) && seen.insert((face, remapped.marker)) {
            compact_facets.push(remapped);
        }
    }

    (compact_points, compact_tets, compact_facets)
}

pub(super) fn surface_winding_number(
    points: &[Point],
    facets: &[RecoveredFacet],
    shell: &[usize],
    point: Point,
) -> f64 {
    let solid_angle: f64 = shell
        .iter()
        .map(|&idx| {
            let facet = facets[idx];
            let [a, b, c] = facet.nodes;
            triangle_solid_angle(point, points[a], points[b], points[c])
        })
        .sum();
    solid_angle / (4.0 * std::f64::consts::PI)
}

pub(super) fn suppress_one_constraint_steiner(
    fixed_point_count: usize,
    points: &mut Vec<Point>,
    facets: &mut Vec<RecoveredFacet>,
) -> bool {
    // Each candidate costs a full re-Delaunay plus a recovery pass, so only
    // the most recently inserted Steiner points are tried per round. Older
    // points get their turn on later rounds as newer ones collapse away.
    const MAX_CANDIDATES_PER_ROUND: usize = 8;
    let first_candidate = points
        .len()
        .saturating_sub(MAX_CANDIDATES_PER_ROUND)
        .max(fixed_point_count);
    for candidate in first_candidate..points.len() {
        let Some((candidate_points, candidate_facets)) =
            collapse_steiner_candidate(points, facets, candidate)
        else {
            continue;
        };
        if validate_recovered_constraints_without_steiner(&candidate_points, &candidate_facets) {
            *points = candidate_points;
            *facets = candidate_facets;
            return true;
        }
    }
    false
}

pub(super) fn collapse_steiner_candidate(
    points: &[Point],
    facets: &[RecoveredFacet],
    candidate: usize,
) -> Option<(Vec<Point>, Vec<RecoveredFacet>)> {
    let mut remaining = Vec::new();
    let mut incident_by_marker: HashMap<i32, Vec<RecoveredFacet>> = HashMap::new();

    for &facet in facets {
        if facet.nodes.contains(&candidate) {
            incident_by_marker
                .entry(facet.marker)
                .or_default()
                .push(facet);
        } else {
            remaining.push(facet);
        }
    }

    let mut markers: Vec<i32> = incident_by_marker.keys().copied().collect();
    markers.sort_unstable();
    let mut collapsed = Vec::new();
    for marker in markers {
        let Some(incident) = incident_by_marker.remove(&marker) else {
            continue;
        };
        let mut vertices = Vec::new();
        for facet in incident {
            for node in facet.nodes {
                if node != candidate && !vertices.contains(&node) {
                    vertices.push(node);
                }
            }
        }
        if vertices.len() != 3 {
            return None;
        }
        collapsed.push(RecoveredFacet {
            nodes: [vertices[0], vertices[1], vertices[2]],
            marker,
        });
    }

    remaining.extend(collapsed);

    let mut remapped_points = Vec::with_capacity(points.len() - 1);
    remapped_points.extend_from_slice(&points[..candidate]);
    remapped_points.extend_from_slice(&points[candidate + 1..]);

    let mut seen = HashSet::new();
    let mut remapped_facets = Vec::with_capacity(remaining.len());
    for mut facet in remaining {
        for node in &mut facet.nodes {
            if *node == candidate {
                return None;
            }
            if *node > candidate {
                *node -= 1;
            }
        }
        if seen.insert((sorted3(facet.nodes), facet.marker)) {
            remapped_facets.push(facet);
        }
    }

    Some((remapped_points, remapped_facets))
}

/// TetGen-style facet completion: a missing constraint facet counts as
/// recovered when the current mesh already tiles its planar region with
/// coplanar faces. The 3D flip table cannot perform in-plane diagonal swaps
/// (the ring around an in-plane edge is never strictly convex in coplanar
/// configurations), so an input triangle whose interior the 2D Delaunay
/// tiles with different diagonals would otherwise be split by Steiner
/// points forever. Adopting the in-situ tiling satisfies the constraint
/// exactly — same plane, same region, same marker — with no new points.
///
/// Returns the adopted sub-facets, or `None` when the region is not fully
/// tiled (skew tets still pierce the plane there).
pub(super) fn try_adopt_facet_tiling(
    points: &[Point],
    faces: &HashSet<[usize; 3]>,
    facet: RecoveredFacet,
) -> Option<Vec<RecoveredFacet>> {
    let a = points[facet.nodes[0]];
    let b = points[facet.nodes[1]];
    let c = points[facet.nodes[2]];
    let area = triangle_area_3d(&a, &b, &c);
    if area == 0.0 {
        return None;
    }
    let mut adopted = Vec::new();
    let mut covered = 0.0;
    for &face in faces {
        if face == sorted3(facet.nodes) {
            continue;
        }
        let p = points[face[0]];
        let q = points[face[1]];
        let r = points[face[2]];
        if robust::orient3d(rc3(a), rc3(b), rc3(c), rc3(p)) != 0.0
            || robust::orient3d(rc3(a), rc3(b), rc3(c), rc3(q)) != 0.0
            || robust::orient3d(rc3(a), rc3(b), rc3(c), rc3(r)) != 0.0
        {
            continue;
        }
        // A centroid inside the requested facet is not sufficient: a larger
        // coplanar face can straddle the facet boundary while retaining an
        // interior centroid.  A triangular facet is convex, so requiring all
        // three candidate vertices to be inside (including its boundary)
        // proves that the complete candidate face is contained before its
        // area participates in the exact-tiling check below.
        if !point_in_or_on_triangle_3d(p, a, b, c)
            || !point_in_or_on_triangle_3d(q, a, b, c)
            || !point_in_or_on_triangle_3d(r, a, b, c)
        {
            continue;
        }
        let centroid = Point::new_3d(
            (p.x + q.x + r.x) / 3.0,
            (p.y + q.y + r.y) / 3.0,
            (p.z + q.z + r.z) / 3.0,
        );
        if !centroid_in_triangle_2d(centroid, a, b, c) {
            continue;
        }
        adopted.push(RecoveredFacet {
            nodes: orient_coplanar_face_like(points, face, facet.nodes),
            marker: facet.marker,
        });
        covered += triangle_area_3d(&p, &q, &r);
    }
    adopted.sort_by_key(|candidate| sorted3(candidate.nodes));
    if !adopted.is_empty()
        && (covered - area).abs() <= 1e-9 * area
        && facet_tiling_has_disjoint_interiors(points, &adopted)
    {
        Some(adopted)
    } else {
        None
    }
}

fn orient_coplanar_face_like(
    points: &[Point],
    mut face: [usize; 3],
    reference: [usize; 3],
) -> [usize; 3] {
    let plane = dominant_projection_plane(
        points[reference[0]],
        points[reference[1]],
        points[reference[2]],
    );
    let reference_sign = robust::orient2d(
        project2(points[reference[0]], plane),
        project2(points[reference[1]], plane),
        project2(points[reference[2]], plane),
    );
    let face_sign = robust::orient2d(
        project2(points[face[0]], plane),
        project2(points[face[1]], plane),
        project2(points[face[2]], plane),
    );
    if reference_sign.signum() != face_sign.signum() {
        face.swap(1, 2);
    }
    face
}

/// Connected input facets with the same marker and plane form one semantic
/// surface patch. Internal input diagonals are not constraints on that patch:
/// an existing tetrahedral face may cross one while remaining wholly inside
/// the patch (notably on annular caps).
pub(super) fn coplanar_facet_patch_groups(
    points: &[Point],
    facets: &[RecoveredFacet],
) -> Vec<Vec<usize>> {
    let mut edge_to_facets: HashMap<[usize; 2], Vec<usize>> = HashMap::new();
    for (index, facet) in facets.iter().enumerate() {
        for edge in triangle_edges(facet.nodes).map(sorted2) {
            edge_to_facets.entry(edge).or_default().push(index);
        }
    }

    let mut visited = vec![false; facets.len()];
    let mut groups = Vec::new();
    for seed in 0..facets.len() {
        if visited[seed] {
            continue;
        }
        visited[seed] = true;
        let mut group = Vec::new();
        let mut queue = VecDeque::from([seed]);
        while let Some(index) = queue.pop_front() {
            group.push(index);
            let facet = facets[index];
            let [a, b, c] = facet.nodes.map(|node| points[node]);
            for edge in triangle_edges(facet.nodes).map(sorted2) {
                for &neighbor in edge_to_facets.get(&edge).into_iter().flatten() {
                    if visited[neighbor] || facets[neighbor].marker != facet.marker {
                        continue;
                    }
                    let coplanar = facets[neighbor].nodes.into_iter().all(|node| {
                        robust::orient3d(rc3(a), rc3(b), rc3(c), rc3(points[node])) == 0.0
                    });
                    if coplanar {
                        visited[neighbor] = true;
                        queue.push_back(neighbor);
                    }
                }
            }
        }
        groups.push(group);
    }
    groups
}

/// Adopt the current tetrahedral faces that tile an entire coplanar patch.
/// Patch-boundary crossings and enclosed hole boundaries are rejected before
/// the disjoint-area coverage check, so internal diagonals may change without
/// filling an annular hole or leaking beyond the requested surface.
pub(super) fn try_adopt_facet_patch_tiling(
    points: &[Point],
    faces: &HashSet<[usize; 3]>,
    facets: &[RecoveredFacet],
) -> Option<Vec<RecoveredFacet>> {
    let first = *facets.first()?;
    let [a, b, c] = first.nodes.map(|node| points[node]);
    let area: f64 = facets
        .iter()
        .map(|facet| {
            let [p, q, r] = facet.nodes.map(|node| points[node]);
            triangle_area_3d(&p, &q, &r)
        })
        .sum();
    if area == 0.0 {
        return None;
    }

    let mut edge_counts: HashMap<[usize; 2], usize> = HashMap::new();
    for facet in facets {
        for edge in triangle_edges(facet.nodes).map(sorted2) {
            *edge_counts.entry(edge).or_default() += 1;
        }
    }
    let boundary_edges: Vec<_> = edge_counts
        .into_iter()
        .filter_map(|(edge, count)| (count == 1).then_some(edge))
        .collect();
    let boundary_nodes: HashSet<_> = boundary_edges.iter().flatten().copied().collect();

    let mut adopted = Vec::new();
    let mut covered = 0.0;
    for &face in faces {
        let [p, q, r] = face.map(|node| points[node]);
        if [p, q, r]
            .into_iter()
            .any(|point| robust::orient3d(rc3(a), rc3(b), rc3(c), rc3(point)) != 0.0)
        {
            continue;
        }
        let centroid = Point::new_3d(
            (p.x + q.x + r.x) / 3.0,
            (p.y + q.y + r.y) / 3.0,
            (p.z + q.z + r.z) / 3.0,
        );
        if !facets.iter().any(|facet| {
            let [u, v, w] = facet.nodes.map(|node| points[node]);
            point_in_or_on_triangle_3d(centroid, u, v, w)
        }) {
            continue;
        }
        if triangle_edges(face).into_iter().any(|candidate| {
            boundary_edges.iter().any(|boundary| {
                segments_properly_cross_coplanar_2d(
                    points,
                    candidate[0],
                    candidate[1],
                    boundary[0],
                    boundary[1],
                    first.nodes,
                )
            })
        }) {
            continue;
        }
        if boundary_nodes
            .iter()
            .copied()
            .any(|node| !face.contains(&node) && point_in_triangle_3d(points[node], p, q, r))
        {
            continue;
        }
        adopted.push(RecoveredFacet {
            nodes: orient_coplanar_face_like(points, face, first.nodes),
            marker: first.marker,
        });
        covered += triangle_area_3d(&p, &q, &r);
    }
    adopted.sort_by_key(|candidate| sorted3(candidate.nodes));
    if !adopted.is_empty()
        && (covered - area).abs() <= 1e-9 * area
        && facet_tiling_has_disjoint_interiors(points, &adopted)
    {
        Some(adopted)
    } else {
        None
    }
}
